(async()=>{
  const E=window.__echoes; const evs=[];
  for (const t of ['room_enter','wave_start','room_cleared','reward_offer','waystone_hit','glint_gain']) E.on(t,(ev)=>evs.push(t+' t'+ev.tick+' '+JSON.stringify(Object.keys(ev).filter(k=>k!=='tick'&&k!=='type').slice(0,4).reduce((o,k)=>{o[k]=ev[k];return o;},{}))));
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  E.cmd('startRun');
  const frame=E.cmd('runState').frame; const target=frame.defendAt[0];
  E.cmd('skipToRoom',target);
  const t0=E.tick; let guard=0;
  while(guard++<800){
    const v=E.cmd('runState');
    if(v.phase!=='combat') break;
    E.cmd('killAllEnemies');
    await sleep(90);
  }
  const v=E.cmd('runState');
  const room=E.state().room;
  return {defendRoom:target, ticksInRoom:E.tick-t0, seconds:+((E.tick-t0)/60).toFixed(1), phase:v.phase, reward:v.reward&&{type:v.reward.type,id:v.reward.id}, wallet:v.wallet, room, evs:evs.slice(0,26)};
})()
